import java.util.*;

class Solution {
    public int[] createTargetArray(int[] nums, int[] index) {
        List<Integer> target = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            target.add(index[i], nums[i]);
        }

        int[] ans = new int[target.size()];
        for (int i = 0; i < target.size(); i++) {
            ans[i] = target.get(i);
        }
        return ans;
    }
}

class Solution {
    public int[] createTargetArray(int[] nums, int[] index) {
        int[] target = new int[nums.length];
        int size = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = size; j > index[i]; j--) {
                target[j] = target[j - 1];
            }
            target[index[i]] = nums[i];
            size++;
        }
        return target;
    }
}

import java.util.*;

class Solution {
    public int[] createTargetArray(int[] nums, int[] index) {
        LinkedList<Integer> target = new LinkedList<>();
        for (int i = 0; i < nums.length; i++) {
            target.add(index[i], nums[i]);
        }

        int[] answer = new int[target.size()];
        int i = 0;
        while (i < target.size()) {
            answer[i] = target.get(i);
            i++;
        }
        return answer;
    }
}

class Solution {
    public int[] createTargetArray(int[] nums, int[] index) {
        int n = nums.length;
        int[] answer = new int[n];
        boolean[] used = new boolean[n];

        for (int i = n - 1; i >= 0; i--) {
            int emptyRank = index[i];
            for (int position = 0; position < n; position++) {
                if (used[position]) {
                    continue;
                }
                if (emptyRank == 0) {
                    answer[position] = nums[i];
                    used[position] = true;
                    break;
                }
                emptyRank--;
            }
        }
        return answer;
    }
}
